import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the product description.
 *
 * A recipe rather than Chakra props because the content is a parsed node tree — `<p>`, `<ul>`,
 * `<li>`, `<br>` — and only a style object can reach those descendants. Chakra props and
 * `textStyle` apply to the wrapper alone.
 *
 * Two deliberate decisions, both flagged for the designer:
 *
 *  - **List markers stay on; the indent is what has to be restated.** Chakra's global reset
 *    applies `:where(ol, ul) { margin: 0; padding: 0; }` and nothing else — `list-style` does
 *    not appear anywhere in `@chakra-ui/css-reset`, so the UA's `disc` marker survives the reset
 *    untouched and it is only the indent that is lost. Markers are `list-style-position: outside`
 *    by default, so with the padding zeroed they hang outside the element's content box and into
 *    whatever sits to its left — here, the image gallery beside a 218px info column. The indent
 *    below puts them back inside it. No DS spec exists for the description's list treatment.
 *  - **No responsive inset.** The mobile design insets the whole content column from the page
 *    gutter, which the page owns (`grid.containerPadding.base`); nothing in the DS insets the
 *    description within that column, so nothing is added here.
 */

/**
 * Rhythm between block children of the description.
 *
 * Measured value: none — the DS specifies 20px *within the text group* (name / price /
 * description), which the `ZimmProductContent` molecule owns, and says nothing about spacing
 * between paragraphs inside the description itself. 20px (`spacing.l`) is carried over from
 * that group rhythm rather than invented, because leaving the blocks flush is visibly wrong.
 * Missing token: none — the value maps exactly onto `spacing.l`.
 * Owner: UI designer, batched with the 28px / 44px gap questions.
 */
const SPACE_BETWEEN_BLOCKS = 'var(--zimm-scale-l)'; // 20px

/**
 * Indent for the description's construction-detail list, so its `disc` markers sit inside the
 * info column rather than overhanging it (see the docblock above for why the reset leaves this
 * to be restated).
 *
 * Measured value: none — no DS spec covers the description's list treatment, so 16px is a
 * provisional choice pending sign-off, not a design decision settled in this file.
 * Owner: UI designer, batched with the 28px / 44px gap questions.
 *
 * Why 16px holds up in the meantime: the description renders at `textStyle: 'body2'` (`fontSize`
 * `2xs` = 0.875rem/14px), so 16px is ~1.14em. The UA default it stands in for is 40px, which
 * would spend nearly a fifth of the 218px info column on the indent alone.
 * Missing token: none — the value maps exactly onto `spacing.m`.
 */
const SPACE_LIST_INDENT = 'var(--zimm-scale-m)'; // 16px

export const ZimmProductDescription = {
  baseStyle: {
    margin: 0,
    color: 'var(--zimm-color-text-default)',
    // Declared here rather than as a `textStyle=` on the element: `@chakra-ui/system`'s
    // `toCSSObject` assigns `styleProps` *after* `__css` (`assignAfter({}, __css, finalBaseStyle,
    // filterUndefined(styleProps), sx)`, dist/index.js lines 204-213), and `assignAfter`
    // re-inserts a duplicate key — so an element `textStyle=` displaces this one rather than
    // merging into it. Keeping it here means one surface owns it. It applies to the wrapper and
    // the parsed descendants inherit it, so the rules below only need to restate box metrics.
    textStyle: 'body2',

    // Both rules below are deliberately written as `& > *`, not `& > p` / `& > ul`. An
    // element-named selector is more specific than `& > * + *`, so the reset would win and the
    // rhythm would never apply — the same trap the molecule's recipe documents. At equal
    // specificity the later key in this object wins, which is the rhythm rule.
    '& > *': {
      marginBlock: 0,
    },
    '& > * + *': {
      marginBlockStart: SPACE_BETWEEN_BLOCKS,
    },
    '& ul, & ol': {
      paddingInlineStart: SPACE_LIST_INDENT,
    },
  } satisfies SystemStyleObject,
};

